{"text":"[Reading 27 lines from start (total: 27 lines, 0 remaining)]\n\n\n\"\"\"\nContinual Learning Worker - เรียนไปเรื่อยๆ ไม่ลืมของเก่า\nต่างจาก LLM ที่เทรนรอบเดียวแล้วจบ\nEWC (Elastic Weight Consolidation) กันลืม\n\"\"\"\nclass ContinualLearningWorker:\n    def __init__(self):\n        self.tasks_learned = []\n        self.forgetting_rate = 0.0\n        \n    def learn_new_task(self, task_name, data):\n        print(f\"📚 Continual Learning - New task: {task_name} - {len(data)} samples\")\n        # EWC: ป้องกันลืม task เก่า\n        if self.tasks_learned:\n            # คำนวณ Fisher matrix เพื่อ lock weights สำคัญของ task เก่า\n            print(f\"   EWC: Protecting {len(self.tasks_learned)} old tasks - Forgetting {self.forgetting_rate:.1%} only\")\n        \n        self.tasks_learned.append(task_name)\n        # Simulate forgetting\n        self.forgetting_rate = max(0, self.forgetting_rate + 0.01 - 0.005)\n        return {\"task\": task_name, \"total_tasks\": len(self.tasks_learned), \"forgetting\": self.forgetting_rate}\n\nif __name__ == \"__main__\":\n    worker = ContinualLearningWorker()\n    worker.learn_new_task(\"Bull Market 2023\", [1,2,3])\n    worker.learn_new_task(\"Bear Market 2024\", [4,5,6])\n\n[executed on device: 10_3_6_9 (85294689-03d5-431e-abd5-9e27d4c94814)]"}